// Piezas de los talleres (una fila por pieza, una entrada por opción) de las tres misiones jugables: MER-3, LUN-3 y COM-1.
// Reglas (mecanicas-del-juego.md §5, §10):
//  - Todo número es { v, conf, src } y, si v es null, lleva `juego` (el motor usa x.v ?? x.juego ?? 0).
//  - Real: V (leído), A (secundaria). Sin dato público: EST (estimación calculada con una ecuación citada; lleva `ec` {es,en}
//    con la fórmula y sus entradas) o, si no hay ecuación posible, J(...) con el GAP si existe, si no 'JUEGO'.
//  - Ecuaciones usadas (investigacion-instrumentos-2.md, parte C): C3 (volumen = masa / densidad) y C11 (masa de batería).
//    Volumen de instrumento: ρ = 230 kg/m3, la mediana de LEXI (162), ALICE (230) y MERTIS (740) → 1 kg ≈ 4,35 L.
//    Batería: m = E / (DoD × e), e = 150 Wh/kg (límite bajo de los packs de ion-litio de la NASA SoA, 150-250 Wh/kg).
//  - Precios: regla provisional de Mateo (propuesta-misiones-mateo.md §1.3): INF con src 'PRECIO' o la fuente de la media real;
//    plataforma pendiente (GAP-P16) → J. Los coeficientes de NICM/SSCM no son públicos (C4): ajustar uno sería inventarlo.
//  - Cada opción trae SIEMPRE los cinco números (masa, potencia, volumen, tasa, precio) y `aporta`; lo que no aplica es 0 [INF].
//  - Cada opción trae `pros` y `contras` ({es,en}, ≤ 8 palabras) y, si fue la real de la misión de referencia, `referencia: true`
//    (la UI NO debe mostrarlo al jugador). Los nombres de opción son neutros: no delatan la respuesta.
//  - Cada pieza trae `usoPara` {es,en}: qué mide o hace, el principio físico y la pregunta que responde (sin nombrar el objetivo).
//  - Ids: los del catálogo de Mateo (LE-, ME-, CE-) para trazabilidad. Las piezas que el catálogo no tiene (computador, actitud,
//    guiado) llevan prefijo JG- (juego) y la misión en el id: JG-MER-*, JG-LUN-*, JG-COM-*.
//  - Las masas "reales" de las estructuras son las totales de las fuentes menos lo que lleva dentro, y la propulsión va en la ruta
//    (ruta.masa): MPO 1230 − 85 de ciencia = 1145 kg (BC-01); Rosetta 2900 − 1670 propelente − 165 ciencia = 1065 kg (CM-01).
//  - Volumen: `aporta.volumen` de la estructura es el real cuando existe (9,0 m³ del MPO, 11,8 m³ de Rosetta: envolvente exterior).
//    Los volúmenes de las piezas de plataforma son JUEGO (sin ecuación pública) y están calibrados para que la configuración de
//    referencia ocupe ~90 % de la envolvente (LUN-3: ~97 %, como antes).
//  - Lote 1 (2026-11-15): masas y potencias nuevas de MERTIS, MIXS, BELA (potencia), LMS y LuGRE; volúmenes de instrumento por C3;
//    baterías por C11; envolvente de LE-04 recalibrada de 430 a 465 L por los volúmenes reales de LMS y LuGRE.

const R = (v, conf, src) => ({ v, conf, src });
const V = (v, src) => R(v, 'V', src);
const A = (v, src) => R(v, 'A', src);
const I = (v, src = 'JUEGO') => R(v, 'INF', src);
const J = (juego, src = 'JUEGO') => ({ v: null, conf: 'JUEGO', src, juego });
const Z = () => I(0); // "no aplica": cero de diseño

const T = (es, en) => ({ es, en });
// Estimación: sin dato público; el valor sale de una ecuación citada (`ec` muestra la fórmula con sus entradas).
const EST = (valor, src, ec) => ({ v: null, conf: 'EST', src, juego: valor, ec });
// Volumen de un instrumento (C3, ρ = 230 kg/m3). `kg` es la masa y `l` el resultado en litros (literal).
const VOL = (kg, l) => EST(l, 'EQ-DENS', T(
  `V ≈ M ÷ ρ = ${String(kg).replace('.', ',')} kg ÷ 0,23 kg/L ≈ ${l} L (ρ ≈ 230 kg/m3, mediana de LEXI, ALICE y MERTIS)`,
  `V ≈ M ÷ ρ = ${kg} kg ÷ 0.23 kg/L ≈ ${l} L (ρ ≈ 230 kg/m3, median of LEXI, ALICE and MERTIS)`));
// Masa de una batería (C11): m = E / (DoD × e), con e = 150 Wh/kg. `kg` es el resultado (literal).
const BAT = (wh, dod, kg) => EST(kg, 'EQ-BAT', T(
  `m = E ÷ (DoD × e) = ${wh} Wh ÷ (${String(dod).replace('.', ',')} × 150 Wh/kg) ≈ ${kg} kg (pack de ion-litio, 150-250 Wh/kg)`,
  `m = E ÷ (DoD × e) = ${wh} Wh ÷ (${dod} × 150 Wh/kg) ≈ ${kg} kg (Li-ion pack, 150-250 Wh/kg)`));

// Pares {es,en} para pros y contras: P(['es', 'en'], ['es', 'en'], ...).
const P = (...pares) => pares.map(([es, en]) => T(es, en));

// opc(id, [es, en], números, pros, contras). `o.referencia`: fue la opción real de la misión de referencia (no se muestra).
const opc = (id, nombre, o = {}, pros = [], contras = []) => ({
  id, nombre: T(nombre[0], nombre[1]),
  masa: o.masa ?? Z(), potencia: o.potencia ?? Z(), volumen: o.volumen ?? Z(), tasa: o.tasa ?? Z(), precio: o.precio ?? Z(),
  aporta: o.aporta ?? {},
  pros, contras,
  ...(o.referencia ? { referencia: true } : {}),
});

const ON = null;                                  // consumidor sin decisión de uso: el motor lo cuenta siempre encendido (24 h)
const USO = (def, max = 24) => ({ min: 0, max, def });

// pz(id, rol, categoria, [es, en] nombre, [es, en] descripción, [es, en] usoPara, misiones, extra, opciones)
const pz = (id, rol, categoria, nombre, desc, usoPara, misiones, extra, opciones) => ({
  id, rol, categoria, nombre: T(nombre[0], nombre[1]), desc: T(desc[0], desc[1]), usoPara: T(usoPara[0], usoPara[1]), misiones,
  enSombra: extra.enSombra ?? false, uso: extra.uso ?? null, opciones,
});

